} else {
  static constexpr nsLiteralCString kActionLogIds[] = {
      ""_ns,
      ""_ns,                                    // 0, 1 (unused)
      "filter-action-log-priority"_ns,          // 2
      "filter-action-log-deleted"_ns,           // 3
      "filter-action-log-read"_ns,              // 4
      "filter-action-log-kill"_ns,              // 5
